-- =============================================================================
-- Mapping: M_DPA_SUM_FACT_GMS_DLY_DOG_RGSTR
-- =============================================================================

-- [TABLE_READ] Step: read_DPA_FACT_GMS_DLY_DOG_RGSTR
-- Table: DPA_FACT_GMS_DLY_DOG_RGSTR
-- Connection: DPA
SELECT * FROM DPA_FACT_GMS_DLY_DOG_RGSTR;

-- [SOURCE_QUALIFIER] Step: apply_SQ_DPA_FACT_GMS_DLY_DOG_RGSTR
select 
(select time_dmns_key from dds_dmns_time where time_val_date=to_date($$v_snsh_date,'yyyyMMdd') and time_dmns_key<200000000) time_dmns_key,
nvl(est_scd_key,0),
sum(aprv_cnt) aprv_cnt, sum(aprv_cncl_cnt) aprv_cncl_cnt, 
sum(auth_dog_pnt_allt_case_cnt) auth_dog_pnt_allt_case_cnt, 
sum(unauth_dog_pnt_allt_case_cnt) unauth_dog_pnt_allt_case_cnt
, 0, sysdate, null
from (
select ee.hse_est_type_code, ee.hse_est_code, aprv_cnt, aprv_cncl_cnt, auth_dog_pnt_allt_case_cnt, unauth_dog_pnt_allt_case_cnt
from (
select gs.hse_est_key, 
count(case when gs.dog_aply_sts_code in ('VLD','ND','NV') then 1 end) aprv_cnt,
count(case when gs.dog_aply_sts_code='DEL' then 1 end) aprv_cncl_cnt,
0 auth_dog_pnt_allt_case_cnt, 0 unauth_dog_pnt_allt_case_cnt
from sor_gms_dog_aply_rgstr g, sor_gms_dog_aply_rgstr_sts gs, sor_gms_dog_aply_ownr o, sor_gms_dog_aply_ownr_sts os
where g.dog_aply_key=os.dog_aply_key
and g.dog_aply_key=gs.dog_aply_key
and to_date($$v_snsh_date,'yyyyMMdd') between gs.bgn_date and gs.end_date
and o.dog_aply_ownr_key=os.dog_aply_ownr_key
and to_date($$v_snsh_date,'yyyyMMdd') between os.bgn_date and os.end_date
group by gs.hse_est_key
union all
select cs.hse_est_key, 0, 0,
count(distinct case when ts.msd_schm_type_code='SCHM_DOG' then t.msd_txn_key end) auth_dog_pnt_allt_case_cnt,
count(distinct case when ts.msd_schm_type_code='SCHM_DOM' then t.msd_txn_key end) unauth_dog_pnt_allt_case_cnt
from sor_gms_msd_txn t, sor_gms_msd_txn_sts ts, sor_gms_msd_tncy_txn tc, sor_gms_msd_tncy_txn_sts tcs, 
sor_gms_msd_tncy c, sor_gms_msd_tncy_sts cs, 
sor_gms_ref_msd_code r, sor_gms_ref_msd_code_sts rs,
sor_gms_srf_ref_code s, sor_gms_srf_ref_code_sts ss
where (ts.msd_schm_type_code='SCHM_DOG' or (ts.msd_schm_type_code='SCHM_DOM' and rs.msd_code in ('B3','B4')))
and ts.msd_type_code='PNT'
and ts.msd_txn_sts_code!='DEL'
and t.msd_txn_key=tc.msd_txn_key
and c.msd_tncy_key=tc.msd_tncy_key
and tcs.msd_tncy_txn_sts_code='ACTV'
and ts.msd_code_key=r.msd_code_bk
and rs.msd_catg_code=ss.ref_code
and rs.msd_code_sts_code='ACTV'
and ss.ref_code_sts_code='ACTV'
and t.msd_txn_key=ts.msd_txn_key
and to_date($$v_snsh_date,'yyyyMMdd') between ts.bgn_date and ts.end_date
and tc.msd_tncy_txn_key=tcs.msd_tncy_txn_key
and to_date($$v_snsh_date,'yyyyMMdd') between tcs.bgn_date and tcs.end_date
and c.msd_tncy_key=cs.msd_tncy_key
and to_date($$v_snsh_date,'yyyyMMdd') between cs.bgn_date and cs.end_date
and r.msd_code_key=rs.msd_code_key
and to_date($$v_snsh_date,'yyyyMMdd') between rs.bgn_date and rs.end_date
and s.ref_code_key=ss.ref_code_key
and to_date($$v_snsh_date,'yyyyMMdd') between ss.bgn_date and ss.end_date
group by cs.hse_est_key
) a, (select e.hse_est_bk, es.hse_est_type_code, es.hse_est_code from sor_gms_sif_ndms_hse_est e, sor_gms_sif_ndms_hse_est_sts es
where e.hse_est_key=es.hse_est_key and to_date($$v_snsh_date,'yyyyMMdd') between es.bgn_date and es.end_date) ee
where a.hse_est_key=ee.hse_est_bk (+)
) b, (select est_scd_key, est_type_code, est_code from dds_hrchy_gms_est where to_date($$v_snsh_date,'yyyyMMdd') between bgn_date and end_date) e
where b.hse_est_type_code=e.est_type_code (+)
and b.hse_est_code=e.est_code (+)
group by est_scd_key;

